-- PT104-S4-Q3. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT104-S4-Q3$batch09$ AND q.stimulus=$batch09$A just government never restricts the right of its citizens to act upon their desires except when their acting upon their desires is a direct threat to the health or property of other of its citizens.$batch09$ AND q.prompt=$batch09$Which one of the following judgments most closely conforms to the principle cited above?$batch09$ AND q.correct_choice=$batch09$A$batch09$) THEN RAISE EXCEPTION 'Question changed: PT104-S4-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT104-S4-Q3$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT104-S4-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$A just government never restricts citizens from acting on their desires, except when acting on them directly threatens other citizens' health or property.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$Put the judgment on the right. If a just government restricts something, that activity directly threatens others' health or property. If an activity poses no such threat, a just government leaves it alone. The rule only tells us what a just government does. It says nothing about what an unjust government would do.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A judgment where a just government allows the harmless activity and restricts only the one that directly threatens others.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT104-S4-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Buying a sports car threatens no one, so a just government wouldn't ban the sale. Racing it without limits on public highways directly threatens other people's health and property, so restricting that fits the exception. Both halves of A line up with the rule.$batch09$), ($batch09$B$batch09$, $batch09$Abolishing services that don't require labor isn't restricting anyone's desires. And the rule never says what an unjust government would do.$batch09$), ($batch09$C$batch09$, $batch09$Handing out emergency funds isn't a restriction. The rule says nothing about who gets aid.$batch09$), ($batch09$D$batch09$, $batch09$Magazines and movies that criticize the government don't directly threaten anyone's health or property. A just government couldn't censor them.$batch09$), ($batch09$E$batch09$, $batch09$E predicts what an unjust government would do. The rule only describes just governments, so it can't tell us how an unjust one behaves.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT104-S4-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
